<template>
  <div class="page-container page-height-limit tr-builder-page">
    <!-- Header — title left, actions right. Same shape as the validation-rule
         builder: a read-only banner replaces Save for system defaults. -->
    <div class="row items-center justify-between q-mb-md">
      <div>
        <div class="text-h6 color-primary">
          {{ isEdit ? $t('edit_rule') : $t('new_rule') }}
        </div>
        <div class="text-body2 text-grey-7">
          {{ $t('transformation_rules') }} / {{ isEdit ? model.display_name : $t('new_rule') }}
        </div>
      </div>
      <div class="row items-center q-gutter-sm">
        <template v-if="isReadOnly">
          <q-banner dense class="bg-warning text-white">
            <template v-slot:avatar>
              <q-icon name="lock" color="white" size="xs" />
            </template>
            {{ $t('default_rule_readonly') }}
          </q-banner>
          <f-btn color="primary" icon="tune" :label="$t('customize')" :loading="customizing" @click="customizeRule" />
        </template>
        <template v-else>
          <f-btn color="primary" icon="save" :label="$t('save')" :loading="saving" @click="save" />
        </template>
      </div>
    </div>

    <div class="tr-form" :class="{ 'tr-form--readonly': isReadOnly }">
      <!-- The generated sentence restates the whole rule in one line, so intent
           can be confirmed without reading every control. -->
      <div class="tr-summary" data-test="tr-summary">
        <!-- Iconify icons render through the global <Icon> component; q-icon
             cannot resolve an `mdi:` name (it would fall back to a Material
             Icons ligature and draw nothing). -->
        <Icon icon="mdi:auto-fix" height="18" width="18" class="tr-summary-icon" />
        <div class="tr-summary-text">
          <template v-for="(tk, ti) in summaryTokens" :key="ti">
            <span v-if="tk.kind === 'field'" class="tr-fld">{{ tk.text }}</span>
            <span v-else-if="tk.kind === 'cond'" class="tr-cnd">{{ tk.text }}</span>
            <b v-else-if="tk.kind === 'strong'">{{ tk.text }}</b>
            <span v-else>{{ tk.text }}</span>
          </template>
        </div>
      </div>

      <div class="tr-grid">
        <div class="tr-main">
          <!-- STEP 1 — What & where -->
          <div class="rb-step">
            <div class="rb-step-head">
              <span class="rb-step-eyebrow">{{ $t('step') }} 1</span>
              <span class="rb-step-title">{{ $t('what_and_where') }}</span>
              <span class="rb-step-hint">{{ $t('choose_the_target') }}</span>
            </div>

            <label class="rb-label">{{ $t('what_does_this_rule_change') }}</label>
            <div class="tr-choose">
              <button
                v-for="choice in scopeChoices"
