                @click="onScopeChange(choice.value)"
              >
                <span class="tr-choice-title">
                  <q-icon v-if="model.scope === choice.value" name="check" size="14px" />
                  {{ $t(choice.titleKey) }}
                </span>
                <span class="tr-choice-desc">{{ $t(choice.descKey) }}</span>
              </button>
            </div>

            <div class="row q-col-gutter-md q-mt-sm">
              <!-- Name + key lead: what it's called before what it touches. -->
              <div class="col-12 col-sm-6 rb-field">
                <label class="rb-label">{{ $t('rule_name') }}</label>
                <q-input
                  outlined dense class="back-white"
                  v-model="model.display_name"
                  :placeholder="$t('name_this_rule')"
                  :readonly="isReadOnly"
                />
              </div>
              <div class="col-12 col-sm-6 rb-field">
                <label class="rb-label">{{ $t('rule_key') }}</label>
                <!-- Machine key: auto-derived from the name for a NEW rule and
                     read-only until the pencil unlocks it; immutable in edit mode. -->
                <q-input
                  outlined dense class="back-white rb-mono"
                  v-model="model.rule_key"
                  :placeholder="$t('rule_key_placeholder')"
                  :readonly="ruleKeyReadonly"
                  @update:model-value="onRuleKeyInput"
                >
                  <template v-if="!isEdit && !isReadOnly && !ruleKeyEditable" #append>
                    <q-icon name="edit" size="xs" class="cursor-pointer" @click="unlockRuleKey">
                      <q-tooltip>{{ $t('edit_rule_key') }}</q-tooltip>
                    </q-icon>
                  </template>
                </q-input>
              </div>

              <!-- Routing rules can only stamp one attribute today, so the
                   target is fixed and shown read-only rather than as a picker. -->
              <div v-if="isRouting" class="col-12 rb-field">
                <label class="rb-label">{{ $t('attribute_to_set') }}</label>
                <q-input outlined dense readonly class="back-white rb-mono" :model-value="docAttributeDisplay" />
                <span class="tr-hint">{{ $t('routing_attribute_hint') }}</span>
              </div>

              <template v-else>
                <div v-if="model.scope === 'column'" class="col-12 col-sm-6 rb-field">
                  <label class="rb-label">{{ $t('table_name') }}</label>
                  <q-select
                    outlined dense emit-value map-options
                    class="back-white"
                    v-model="selectedTable"
                    :options="tableOptions"
                    :loading="loadingTables || loadingColumns"
                    :readonly="isReadOnly"
                    :placeholder="selectedTable ? '' : $t('select_table')"
                    @update:model-value="onTableSelected"
                  />
                </div>
                <div class="col-12 col-sm-6 rb-field">
                  <label class="rb-label">
                    {{ model.scope === 'column' ? $t('target_column') : $t('target_field') }}
                  </label>
                  <q-select
                    outlined dense clearable use-input input-debounce="0" emit-value map-options
                    class="back-white"
                    v-model="model.target_field"
                    :options="targetFieldOptions"
                    :loading="loadingFields"
                    :readonly="isReadOnly"
                    @filter="filterTargetFields"
                    :placeholder="model.target_field ? '' : $t('select_field')"
                  />
                  <span class="tr-hint">{{ $t('rule_writes_result_here') }}</span>
                </div>
              </template>

              <div class="col-12 col-sm-6 rb-field">
                <label class="rb-label">{{ $t('description') }}</label>
                <q-input
                  outlined dense class="back-white"
                  v-model="model.description"
                  :placeholder="$t('description')"
                  :readonly="isReadOnly"
                />
              </div>

              <div class="col-12 col-sm-6 rb-field">
                  <q-checkbox
                    v-model="model.log_execution"
                    :label="$t('log_execution')"
                    dense
                    :disable="isReadOnly"
                  />
              </div>
            </div>
          </div>

          <!-- STEP 2 — When it runs -->
          <div class="rb-step">
            <div class="rb-step-head">
              <span class="rb-step-eyebrow">{{ $t('step') }} 2</span>
              <span class="rb-step-title">{{ $t('when_it_runs') }}</span>
              <span class="rb-step-hint">{{ $t('always_or_on_a_condition') }}</span>
            </div>

            <q-btn-toggle
              v-model="model.when_mode"
              :options="whenModeOptions"
              no-caps unelevated
              class="rb-toggle q-mb-md"
              toggle-color="primary"
              color="white"
              text-color="grey-8"
              :disable="isReadOnly"
              @update:model-value="onWhenModeChange"
            />

            <p v-if="model.when_mode === 'always'" class="tr-always-note">
              {{ $t('runs_on_every_doc_processed', { docType: doc_type_key }) }}
            </p>
            <!-- Reuses the validation builder's condition editor, nested
                 sub-groups included: the applies_when tree is the same shape on
                 both endpoints, and this builder's serializer, parser, preview
                 evaluator and sentence all walk sub-groups already. -->
            <ConditionGroup
              v-else
              :group="model.group"
              :field-options="allFields"
              :origin-options="originOptions"
              :sub-org-options="subOrgOptions"
              :readonly="isReadOnly"
            />
          </div>

          <!-- STEP 3 — The pipeline -->
          <div class="rb-step">
            <div class="rb-step-head">
              <span class="rb-step-eyebrow">{{ $t('step') }} 3</span>
              <span class="rb-step-title">{{ $t('the_pipeline') }}</span>
              <span class="rb-step-hint">{{ $t('read_transform_write') }}</span>
            </div>

            <!-- READ FROM endcap -->
            <div class="tr-endcap">
              <div class="tr-cap-label">
                {{ $t('read_from') }}
                <span class="tr-tag">{{ sourceTag }}</span>
              </div>
              <div class="tr-src-modes">
                <button
                  type="button"
                  class="tr-src-mode"
                  :class="{ 'tr-src-mode--on': !isDeriving }"
                  :disabled="isReadOnly"
                  data-test="tr-src-self"
                  @click="setSourceMode('self')"
                >
                  {{ isRouting ? $t('assign_a_fixed_sub_organisation') : model.scope === 'column' ? $t('the_column_itself') : $t('the_field_itself') }}
                </button>
                <button
                  type="button"
                  class="tr-src-mode"
                  :class="{ 'tr-src-mode--on': isDeriving }"
                  :disabled="isReadOnly"
                  data-test="tr-src-derive"
                  @click="setSourceMode('derive')"
                >
                  {{ isRouting ? $t('map_from_a_field') : $t('another_field') }}
                </button>
              </div>
              <div v-if="isDeriving" class="tr-src-detail">
                <q-select
                  outlined dense use-input input-debounce="0" emit-value map-options
                  class="back-white"
                  v-model="model.source"
                  :options="sourceFieldOptions"
                  :readonly="isReadOnly"
                  popup-content-class="rb-field-popup"
                  @filter="filterSourceFields"
                  :placeholder="model.source ? '' : $t('select_field')"
                >
                  <template #option="scope">
                    <div :key="scope.opt.value">
                      <div
                        v-if="scope.opt.group && scope.opt.group !== sourceFieldOptions[scope.index - 1]?.group"
                        class="rb-opt-group"
                        :class="{ 'rb-opt-group--first': scope.index === 0 }"
                      >{{ scope.opt.group }}</div>
                      <q-item v-bind="scope.itemProps"><q-item-section>{{ scope.opt.label }}</q-item-section></q-item>
                    </div>
                  </template>
                </q-select>
              </div>
            </div>

            <!-- STEPS -->
            <div class="tr-flow-arrow"><q-icon name="south" size="16px" /></div>

            <div class="tr-steps">
              <StepCard
                v-for="(action, ai) in model.actions"
                :key="ai"
                :action="action"
                :index="ai"
                :total="model.actions.length"
                :open="openStep === ai"
                :readonly="isReadOnly"
                :result="stepResult(ai)"
                :sub-org-options="subOrgOptions"
                @toggle="openStep = openStep === ai ? null : ai"
                @move="(delta: number) => moveStep(ai, delta)"
                @remove="removeStep(ai)"
                @change="(payload: any) => onStepParamChange(ai, payload)"
              />

              <!-- The pipeline can be emptied, so fill the gap between the two
                   endcaps with what's missing. -->
              <div v-if="!model.actions.length" class="tr-steps-empty" data-test="tr-steps-empty">
                <q-icon name="info" size="15px" />
                <span>{{ $t('pipeline_has_no_steps') }}</span>
              </div>
            </div>

            <!-- ADD STEP — grouped menu, filtered by scope. -->
            <div v-if="!isReadOnly" class="tr-addstep-wrap">
              <button type="button" class="tr-addstep" data-test="tr-add-step">
                + {{ $t('add_a_step') }}
                <q-menu anchor="bottom left" self="top left" :offset="[0, 4]">
                  <q-list dense class="tr-step-menu">
                    <template v-for="group in availableActions" :key="group.groupKey">
                      <q-item-label header class="tr-menu-group">{{ $t(group.groupKey) }}</q-item-label>
                      <q-item
                        v-for="type in group.types"
                        :key="type"
                        clickable v-close-popup dense
                        :data-test="'tr-add-' + type"
                        @click="addStep(type)"
                      >
                        <q-item-section avatar class="tr-menu-icon">
                          {{ actionIcon(type) }}
                        </q-item-section>
                        <q-item-section>
                          <q-item-label>{{ $t(actionVerbKey(type)) }}</q-item-label>
                          <q-item-label caption>{{ $t(actionHintKey(type)) }}</q-item-label>
                        </q-item-section>
                      </q-item>
                    </template>
                  </q-list>
                </q-menu>
              </button>
            </div>

            <!-- WRITE TO endcap -->
            <div class="tr-flow-arrow"><q-icon name="south" size="16px" /></div>

            <div class="tr-endcap tr-endcap--out">
              <div class="tr-cap-label tr-cap-label--out">
                {{ $t('write_to') }}
                <span class="tr-tag">{{ outputTag }}</span>
              </div>
              <div class="tr-cap-val">
                <span class="rb-mono-text">{{ isRouting ? docAttributeKey : model.target_field || '—' }}</span>
                <span class="tr-eq">=</span>
                <span class="tr-cap-v">{{ orEmpty(finalPreview) }}</span>
              </div>
            </div>

            <!-- Guidance: non-idempotent steps applied in place silently keep
                 mutating the field on every re-process, so warn and offer the fix. -->
            <div v-if="nonIdempotentWarning" class="tr-note tr-note--warn">
              <q-icon name="warning" size="16px" />
              <div>
                <b>{{ $t('read_from_another_field') }}</b>
                {{ $t('non_idempotent_steps_warning', { steps: nonIdempotentWarning, field: model.target_field }) }}
                <div class="q-mt-xs">
                  <q-btn
                    dense flat no-caps size="sm" color="primary"
                    :label="$t('read_from_another_field_action')"
                    @click="setSourceMode('derive')"
                  />
                </div>
              </div>
            </div>
            <div v-else class="tr-note tr-note--info">
              <q-icon name="info" size="16px" />
              <div>
                {{ isRouting ? $t('routing_rule_note', { attr: docAttributeKey }) : $t('result_written_to_field_note', { field: model.target_field || $t('the_field') }) }}
              </div>
            </div>
          </div>
        </div>

        <!-- LIVE PREVIEW — runs the pipeline client-side on a sample value so
             the effect of each step is visible while editing. -->
        <aside class="tr-preview">
          <div class="tr-pv-card">
            <div class="tr-pv-head">
              <span class="tr-pv-title">
                <Icon icon="mdi:speedometer" height="16" width="16" />
                {{ $t('live_preview') }}
              </span>
            </div>
            <div class="tr-pv-body">
              <div class="rb-field">
                <label class="rb-label">
                  {{ $t('sample_input') }} · <span class="tr-tag">{{ sampleFieldName }}</span>
                </label>
                <q-input
                  outlined dense class="back-white rb-mono"
                  v-model="model.sample_input"
                  :placeholder="$t('type_a_sample_value')"
                />
              </div>

              <!-- Step 2's conditions, evaluated against sample values so the
                   preview can say whether the rule would run at all. A field
                   that IS the previewed field reuses the sample input above
                   rather than showing a second box for the same value. -->
              <div v-if="model.when_mode === 'cond' && previewConditionFields.length" class="tr-pv-conditions">
                <label class="rb-label">{{ $t('condition_values') }}</label>
                <div
                  v-for="field in previewConditionFields"
                  :key="field"
                  class="tr-pv-cond-row"
                >
                  <span class="tr-tag tr-pv-cond-field">{{ field }}</span>
                  <q-input
                    v-if="!isSampleField(field)"
                    outlined dense class="back-white rb-mono"
                    :model-value="conditionSamples[field] || ''"
                    :placeholder="$t('value')"
                    @update:model-value="(val) => setConditionSample(field, val)"
                  />
                  <span v-else class="tr-pv-cond-mirror">
                    {{ model.sample_input === '' ? $t('empty_value') : model.sample_input }}
                  </span>
                </div>

                <div
                  class="tr-pv-match"
                  :class="previewMatches ? 'tr-pv-match--yes' : 'tr-pv-match--no'"
                  data-test="tr-preview-match"
                >
                  <q-icon :name="previewMatches ? 'check_circle' : 'remove_circle_outline'" size="15px" />
                  <span>
                    {{ previewMatches ? $t('conditions_match_rule_runs') : $t('conditions_do_not_match_rule_skipped') }}
                  </span>
                </div>
              </div>

              <!-- Dimmed when the conditions rule this document out: the steps
                   below are what WOULD happen, not what does. -->
              <div class="tr-flowlist" :class="{ 'tr-flowlist--skipped': !previewMatches }">
                <div
                  v-for="(node, ni) in previewNodes"
                  :key="ni"
                  class="tr-flownode"
                  :class="{
                    'tr-flownode--result': node.isResult,
                    'tr-flownode--nochange': !node.changed,
                  }"
                >
                  <span
                    class="tr-dot"
                    :class="{ 'tr-dot--in': ni === 0, 'tr-dot--out': node.isResult }"
                  />
                  <div>
                    <div class="tr-flow-cap">
                      {{ $t(node.captionKey) }}
                      <span v-if="!node.changed" class="tr-nochange">· {{ $t('no_change') }}</span>
                    </div>
                    <div class="tr-flow-val" :class="{ 'tr-flow-val--empty': node.display === '' }">
                      {{ orEmpty(node.display) }}
                    </div>
                  </div>
                </div>
              </div>

              <div class="tr-pv-when">
                <q-icon name="schedule" size="14px" />
                <span>
                  {{ model.when_mode === 'always'
                    ? $t('runs_on_every_doc', { docType: doc_type_key })
                    : $t('runs_only_when_conditions_match') }}
                </span>
              </div>

              <!-- What the document actually ends up with. When the conditions
                   don't match the rule writes nothing, so the field keeps its
                   original value — say so explicitly rather than showing the
                   transformed value as if it had been applied. -->
              <div class="tr-pv-outcome" :class="{ 'tr-pv-outcome--skipped': !previewMatches }">
                <span class="tr-pv-outcome-label">
                  {{ isRouting ? docAttributeKey : model.target_field || '—' }}
                </span>
                <q-icon name="east" size="13px" />
                <span class="tr-pv-outcome-val">
                  {{ orEmpty(effectiveOutcome) }}
                </span>
                <span v-if="!previewMatches" class="tr-pv-outcome-note">{{ $t('unchanged') }}</span>
              </div>
            </div>
          </div>
        </aside>
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import { notify, notifyApiError } from 'src/components/notifications/notify';
import { transformationRulesApiService, documentTypeApiService } from 'src/services';
import type {
  TransformationRule,
  TransformationRuleScope,
} from 'src/services/settings/TransformationRulesApiService';
import {
  buildFieldOptions,
  buildTargetFieldOptions,
  loadHeaderFieldOptions,
  loadDocOriginOptions,
  buildAppliesWhenFromGroup,
  CUSTOM_PATH_OPTION,
  newGroup,
  type FieldOption,
} from '../CustomValidationRules/rule-builder-model';
import { useRuleKey } from '../CustomValidationRules/useRuleKey';
import ConditionGroup from '../CustomValidationRules/ConditionGroup.vue';
import StepCard from './StepCard.vue';
import {
  emptyModel,
  fromApiRule,
  assembleApiCore,
  slugify,
  chainValues,
  sharedFieldScope,
  conditionFields,
  evaluateGroup,
  actionsForScope,
  actionMeta,
  newAction,
  defaultParams,
  ruleSentence,
  shortFieldName,
  ACTION_CATALOGUE,
  NON_IDEMPOTENT_ACTIONS,
  DOC_ATTRIBUTE_KEY,
  SCOPE_META,
  SCOPE_ORDER,
  type TransformationBuilderModel,
  type SentenceToken,
} from './transformation-rule-model';
import { conditionPhrases } from './condition-phrases';
import { useDropdownStore } from 'src/store/Dropdown/dropdown.store';

export default defineComponent({
  name: 'TransformationRuleBuilder',
  components: { ConditionGroup, StepCard },
  data() {
    return {
      doc_type_key: '',
      docAttributeKey: DOC_ATTRIBUTE_KEY,
      // Header fields are fetched once; column fields are per-table and loaded
      // on demand when a table is selected.
      cachedHeaderFields: [] as FieldOption[],
      cachedColumnFields: [] as FieldOption[],
      fieldsLoaded: false,
      tableOptions: [] as FieldOption[],
      selectedTable: '',
      loadingTables: false,
      loadingColumns: false,
      loadingFields: false,
      // Condition-picker field list (namespaced + the Custom JSON path escape
      // hatch) and the value vocabularies threaded into it.
      allFields: [] as FieldOption[],
      originOptions: [] as FieldOption[],
      subOrgOptions: [] as FieldOption[],
      // Target-field picker (bare names, scoped to the rule level).
      allTargetFields: [] as FieldOption[],
      targetFieldOptions: [] as FieldOption[],
      // Source picker (namespaced — the pipeline can read any field).
      allSourceFields: [] as FieldOption[],
      sourceFieldOptions: [] as FieldOption[],
      // Which pipeline step is expanded (only one at a time).
      openStep: null as number | null,
      // Preview-only sample values for the fields the conditions reference,
      // keyed by the namespaced field. Never saved with the rule.
      conditionSamples: {} as Record<string, string>,
    };
  },
  computed: {
    isEdit(): boolean {
      return !!this.rule_id;
    },
    isRouting(): boolean {
      return this.model.scope === 'document';
    },
    // The pipeline reads another field rather than the target itself.
    isDeriving(): boolean {
      return !!this.model.source;
    },
    scopeChoices(): { value: TransformationRuleScope; titleKey: string; descKey: string }[] {
      return SCOPE_ORDER.map((scope) => ({
        value: scope,
        titleKey: SCOPE_META[scope].titleKey,
        descKey: SCOPE_META[scope].descKey,
      }));
    },
    whenModeOptions(): { label: string; value: 'always' | 'cond' }[] {
      return [
        { label: this.$t('when_always'), value: 'always' },
        { label: this.$t('only_when'), value: 'cond' },
      ];
    },
    docAttributeDisplay(): string {
      return `${DOC_ATTRIBUTE_KEY} · ${this.$t('sub_organisation_inline')}`;
    },
    // Add-step menu contents for the current scope (routing rules get only the
    // actions that make sense for a document attribute).
    availableActions(): { groupKey: string; types: string[] }[] {
      return actionsForScope(this.model.scope);
    },
    // The field name whose sample value seeds the preview.
    sampleFieldName(): string {
      return this.model.source
        ? shortFieldName(this.model.source)
        : this.model.target_field || '—';
    },
    // Value before the first step, then after each step.
    previewChain(): string[] {
      return chainValues(this.model.sample_input, this.model.actions);
    },
    // One render-ready node per chain entry: the input, then one per step. Doing
    // the caption / display / changed work here keeps the sub-org lookups and
    // the empty-value handling out of the template.
    previewNodes(): { captionKey: string; display: string; changed: boolean; isResult: boolean }[] {
      const chain = this.previewChain;
      return chain.map((value, i) => ({
        captionKey: i === 0 ? 'input_label' : this.actionVerbKey(this.model.actions[i - 1].type),
        display: this.displayValue(value),
        changed: i === 0 || value !== chain[i - 1],
        isResult: i > 0 && i === chain.length - 1,
      }));
    },
    finalPreview(): string {
      const chain = this.previewChain;
      return this.displayValue(chain[chain.length - 1]);
    },
    // Fields the Step 2 conditions reference — the preview needs a sample value
    // for each to decide whether the rule would run.
    previewConditionFields(): string[] {
      return conditionFields(this.model.group);
    },
    // Would this document reach the pipeline at all? Always true in "Always"
    // mode and while no condition has a field chosen yet.
    previewMatches(): boolean {
      if (this.model.when_mode !== 'cond') {
        return true;
      }
      return evaluateGroup(this.model.group, (field: string) => this.conditionValueFor(field));
    },
    // What the target field actually holds afterwards: the pipeline result when
    // the rule runs, otherwise the untouched input.
    effectiveOutcome(): string {
      if (!this.previewMatches) {
        return this.displayValue(this.model.sample_input);
      }
      return this.finalPreview;
    },
    sourceTag(): string {
      if (this.model.source) return shortFieldName(this.model.source);
      return this.isRouting ? this.$t('fixed') : this.model.target_field || '—';
    },
    outputTag(): string {
      return this.isRouting ? this.$t('sub_organisation_inline') : this.model.target_field || '—';
    },
    // Steps in the pipeline that are unsafe to re-run on their own output.
    // Only a problem when transforming the target IN PLACE (no source field).
    nonIdempotentWarning(): string {
      if (this.isRouting || this.model.source) return '';
      const offending = this.model.actions
        .filter((a) => NON_IDEMPOTENT_ACTIONS.includes(a.type))
        .map((a) => this.$t(actionMeta(a.type)?.verbKey || a.type));
      return offending.length ? offending.join(', ') : '';
    },
    // The generated one-line summary, as render tokens. The conditions are
    // serialized with the SAME function the save path uses, so the sentence can
    // never describe a different rule than the one that gets stored (an earlier
    // hand-rolled walk here silently dropped nested groups and `in` lists).
    summaryTokens(): SentenceToken[] {
      const conditions =
        this.model.when_mode === 'cond'
          ? conditionPhrases(
              buildAppliesWhenFromGroup(this.model.group),
              this.model.group.join,
              this.$t,
            )
          : [];
      return ruleSentence(
        {
          scope: this.model.scope,
          target_field: this.isRouting ? DOC_ATTRIBUTE_KEY : this.model.target_field,
          source: this.model.source,
          actions: this.model.actions,
          conditions,
          join: this.model.group.join,
        },
        this.doc_type_key,
        this.$t,
        (value: string) => this.subOrgLabel(value),
      );
    },
  },
  watch: {
    // Customizing a system default navigates from this same route to the new
    // override's id. The settings router-view is unkeyed, so Vue reuses this
    // instance and mounted() does not re-run — reload the rule ourselves.
    '$route.params.rule_id'(newId: string) {
      const id = String(newId || '');
      if (id && id !== this.rule_id) {
        this.rule_id = id;
        this.loadForEdit();
      }
    },
  },
  mounted() {
    this.doc_type_key = String(this.$route.params.doc_type || '');
    this.rule_id = String(this.$route.params.rule_id || '');
    this.loadFieldsOnce().then(() => this.rebuildFieldOptions());
    this.loadTables().then(() => this.ensureTableSelected());
    this.loadOrigins();
    this.loadSubOrgs();
    if (this.isEdit) {
      this.loadForEdit();
    }
  },
  methods: {
    async loadForEdit() {
      // Prefer the row handed over via router state (from the list) to skip a
      // round-trip; otherwise fetch just this one rule by id.
      const stateRule = (history.state && history.state.rule) as TransformationRule | undefined;
      if (stateRule && stateRule.id === this.rule_id) {
        this.applyRule(stateRule);
        return;
      }
      try {
        this.saving = true;
        const rule = await transformationRulesApiService.getById(this.rule_id);
        if (rule && rule.id) {
          this.applyRule(rule);
        } else {
          notify.error(this.$t('rule_not_found'));
        }
      } catch (err) {
        notifyApiError(err);
        logError(err);
      } finally {
        this.saving = false;
      }
    },
    applyRule(rule: TransformationRule) {
      this.isReadOnly = rule.source_badge === 'system_default';
      this.model = fromApiRule(rule);
      this.$nextTick(() => {
        this.rebuildFieldOptions();
        if (this.model.scope === 'column' && this.model.table_name) {
          this.onTableSelected(this.model.table_name);
        } else {
          this.ensureTableSelected();
        }
      });
    },
    // Fetch the header fields ONCE and cache them.
    async loadFieldsOnce() {
      if (this.fieldsLoaded) return;
      try {
        this.loadingFields = true;
        this.cachedHeaderFields = await loadHeaderFieldOptions(this.doc_type_key);
        this.fieldsLoaded = true;
      } catch (err) {
        notifyApiError(err);
        logError(err);
      } finally {
        this.loadingFields = false;
      }
    },
    // Re-group the cached fields for the current scope (no network). Each picker
    // gets its own copy so filtering one never mutates the shared source.
    //
    // The shared builders speak the validation-rule scope vocabulary
    // ('header' | 'line' | 'table'), so a column-scoped transformation rule maps
    // onto 'line' to pick up the row.* namespace.
    rebuildFieldOptions() {
      const sharedScope = sharedFieldScope(this.model.scope);
      const columns = this.model.scope === 'column' ? this.cachedColumnFields : [];
      const base = buildFieldOptions(sharedScope, this.cachedHeaderFields, columns);
      // Condition picker additionally offers the Advanced "Custom JSON path".
      this.allFields = [
        ...base,
        { value: CUSTOM_PATH_OPTION, label: this.$t('custom_json_path'), group: this.$t('advanced') },
      ];
      // The pipeline can READ any namespaced field (no JSON-path escape hatch —
      // a transformation source must be a real, mapped field).
      this.allSourceFields = base.slice();
      this.sourceFieldOptions = this.allSourceFields.slice();
      // The target is a BARE name scoped strictly to the rule level.
      this.allTargetFields = buildTargetFieldOptions(
        sharedScope,
        this.cachedHeaderFields,
        this.cachedColumnFields,
      );
      this.targetFieldOptions = this.allTargetFields.slice();
    },
    async loadOrigins() {
      try {
        this.originOptions = await loadDocOriginOptions();
      } catch (err) {
        logError(err);
      }
    },
    // Sub-organisations feed both the doc.sub_org_id condition picker and the
    // routing rule's set_value target.
    async loadSubOrgs() {
      try {
        const store = useDropdownStore();
        await store.getSubOrgsList();
        this.subOrgOptions = (store.subOrgList as dynamicObj[])
          .filter((o) => o && o.value)
          .map((o) => ({ value: String(o.value), label: String(o.label ?? o.value) }));
      } catch (err) {
        logError(err);
      }
    },
    // '(empty)' rather than a blank gap, used wherever a preview value renders.
    orEmpty(value: string): string {
      return value === '' ? this.$t('empty_value') : value;
    },
    subOrgLabel(value: string): string {
      // The dropdown store indexes id → name; avoid re-scanning the option list
      // (this is called per preview node and per step on every render).
      return this.dropdowns.getSubOrgName(value) || value;
    },
    // A condition on the very field being previewed is driven by the Sample
    // input box, so the user types the value once instead of twice.
    isSampleField(field: string): boolean {
      return !!this.sampleFieldName && shortFieldName(field) === this.sampleFieldName;
    },
    // Resolve a condition field to its preview value.
    conditionValueFor(field: string): string {
      if (this.isSampleField(field)) {
        return this.model.sample_input;
      }
      return this.conditionSamples[field] ?? '';
    },
    setConditionSample(field: string, value: unknown) {
      this.conditionSamples = { ...this.conditionSamples, [field]: String(value ?? '') };
    },
    // A routing rule's pipeline value is a sub-org id — show the branch name.
    displayValue(value: string): string {
      return this.isRouting && value ? this.subOrgLabel(value) : value;
    },
    async loadTables() {
      if (!this.doc_type_key) return;
      try {
        this.loadingTables = true;
        const res = await documentTypeApiService.getTable(this.doc_type_key);
        const list = ((res && res.data) || []) as dynamicObj[];
        this.tableOptions = list
          .filter((t) => t && t.table_name)
          .map((t) => ({ value: String(t.table_name), label: String(t.table_name) }));
      } catch (err) {
        notifyApiError(err);
        logError(err);
      } finally {
        this.loadingTables = false;
      }
    },
    // Fetch one table's columns as BARE field options (the row. namespace is
    // added at build time).
    async loadColumnsForTable(tableName: string): Promise<FieldOption[]> {
      if (!tableName) return [];
      const res = await documentTypeApiService.getDocumentTableColumns(tableName);
      const columns = ((res && res.data) || []) as dynamicObj[];
      return columns
        .filter((col) => col && col.column_name)
        .map((col) => {
          const colType = col.column_type || col.dataType;
          return {
            value: String(col.column_name),
            label: String(col.column_name),
            type: colType ? String(colType) : undefined,
          };
        });
    },
    async onTableSelected(tableName: string | null) {
      this.selectedTable = tableName || '';
      this.model.table_name = this.selectedTable;
      if (!this.selectedTable) {
        this.cachedColumnFields = [];
        this.rebuildFieldOptions();
        return;
      }
      try {
        this.loadingColumns = true;
        this.cachedColumnFields = await this.loadColumnsForTable(this.selectedTable);
        this.rebuildFieldOptions();
      } catch (err) {
        notifyApiError(err);
        logError(err);
      } finally {
        this.loadingColumns = false;
      }
    },
    // Default the table picker to the first table (column scope) so row.*
    // columns are available without an extra click; a no-op once one is chosen.
    ensureTableSelected() {
      if (this.model.scope !== 'column' || this.selectedTable || !this.tableOptions.length) return;
      this.onTableSelected(this.tableOptions[0].value);
    },
    filterTargetFields(val: string, update: (cb: () => void) => void) {
      update(() => {
        this.targetFieldOptions = this.matchFields(this.allTargetFields, val);
      });
    },
    filterSourceFields(val: string, update: (cb: () => void) => void) {
      update(() => {
        this.sourceFieldOptions = this.matchFields(this.allSourceFields, val);
      });
    },
    // Filter a flat list by needle (label or namespaced value). Always returns a
    // NEW array so the bound q-select options never accumulate across cycles.
    matchFields(list: FieldOption[], val: string): FieldOption[] {
      const needle = val.toLowerCase();
      if (!needle) return list.slice();
      return list.filter(
        (f) => f.label.toLowerCase().includes(needle) || f.value.toLowerCase().includes(needle),
      );
    },
    // Changing the rule level rewires target, source and the pipeline: a routing
    // rule can only stamp the doc attribute via set_value, and a field rule
    // cannot use the routing-only actions.
    onScopeChange(scope: TransformationRuleScope) {
      if (this.isReadOnly || this.model.scope === scope) return;
      this.model.scope = scope;
      this.model.sample_input = '';
      if (scope === 'document') {
        this.model.target_field = DOC_ATTRIBUTE_KEY;
        this.model.source = '';
        this.model.table_name = '';
        if (!(this.model.actions.length === 1 && this.model.actions[0].type === 'set_value')) {
          this.model.actions = [newAction('set_value')];
        }
        this.applyDefaultSubOrg();
      } else {
        if (this.model.target_field === DOC_ATTRIBUTE_KEY) this.model.target_field = '';
        // Drop routing-only steps (set_value) that cannot run on a field.
        if (this.model.actions.some((a) => ACTION_CATALOGUE[a.type]?.docOnly)) {
          this.model.actions = [newAction('trim')];
        }
        // A row.* source is only reachable from a column rule.
        if (this.model.source.startsWith('row.') && scope !== 'column') {
          this.model.source = '';
        }
      }
      this.openStep = null;
      this.rebuildFieldOptions();
      this.ensureTableSelected();
    },
    // Seed a routing rule's set_value with the first sub-org so the preview and
    // the summary have something concrete to show.
    applyDefaultSubOrg() {
      const step = this.model.actions[0];
      if (!step || step.type !== 'set_value') return;
      const params = (step.params || {}) as Record<string, unknown>;
      if (!params.value && this.subOrgOptions.length) {
        step.params = { ...params, value: this.subOrgOptions[0].value };
      }
    },
    onWhenModeChange(mode: 'always' | 'cond') {
      // Switching to conditional with an empty tree gives the user one blank row
      // to fill in; switching back to Always drops the tree entirely on save.
      if (mode === 'cond' && !this.model.group.conditions.length) {
        this.model.group = newGroup('all');
        this.model.group.conditions.push({
          kind: 'condition',
          field: '',
          op: 'eq',
          value: '',
          negate: false,
          case_insensitive: false,
          isPath: false,
        });
      }
    },
    // Read-from mode: 'self' transforms the target in place, 'derive' reads
    // another field. Routing rules map the same switch onto fixed vs. mapped.
    setSourceMode(mode: 'self' | 'derive') {
      if (this.isReadOnly) return;
      this.model.sample_input = '';
      if (mode === 'self') {
        this.model.source = '';
        if (this.isRouting && !(this.model.actions.length === 1 && this.model.actions[0].type === 'set_value')) {
          this.model.actions = [newAction('set_value')];
          this.applyDefaultSubOrg();
        }
        return;
      }
      // Derive: pick a sensible default source that isn't the target itself.
      const pool = this.allSourceFields.filter(
        (f) => shortFieldName(f.value) !== this.model.target_field,
      );
      const pick = pool[0] || this.allSourceFields[0];
      this.model.source = pick ? pick.value : '';
      if (this.isRouting && !(this.model.actions.length === 1 && this.model.actions[0].type === 'value_map')) {
        // Mapping a field onto a sub-org is a value_map, not a fixed assignment.
        this.model.actions = [newAction('value_map')];
      }
      this.openStep = null;
    },
    actionIcon(type: string): string {
      return ACTION_CATALOGUE[type]?.icon || '?';
    },
    actionVerbKey(type: string): string {
      return ACTION_CATALOGUE[type]?.verbKey || type;
    },
    actionHintKey(type: string): string {
      return ACTION_CATALOGUE[type]?.hintKey || '';
    },
    // The pipeline value after step `ai`, for the step head's result chip.
    stepResult(ai: number): string {
      // previewNodes[0] is the input, so step `ai` lands at ai + 1.
      return this.previewNodes[ai + 1]?.display ?? '';
    },
    addStep(type: string) {
      this.model.actions.push(newAction(type));
      this.openStep = this.model.actions.length - 1;
    },
    moveStep(index: number, delta: number) {
      const to = index + delta;
      if (to < 0 || to >= this.model.actions.length) return;
      const list = this.model.actions;
      [list[index], list[to]] = [list[to], list[index]];
      // Keep the expanded step expanded after it moves.
      if (this.openStep === index) this.openStep = to;
      else if (this.openStep === to) this.openStep = index;
    },
    removeStep(index: number) {
      this.model.actions.splice(index, 1);
      // An empty pipeline is a valid editing state; validate() enforces the
      // API's "at least one action" rule at save time.
      this.openStep = null;
    },
    // A step edited one of its params. A `struct` param (sanitize's op) changes
    // WHICH other params are shown, so top up from the catalogue defaults to
    // guarantee the newly-revealed param has a value. What the user already
    // typed in the other branch is kept on purpose — toggling op back and forth
    // must not lose it, and the serializer only ever emits the selected branch.
    onStepParamChange(
      index: number,
      payload: { key: string; value: unknown; struct?: boolean },
    ) {
      const action = this.model.actions[index];
      if (!action) return;
      const params = { ...(action.params || {}), [payload.key]: payload.value };
      if (payload.struct) {
        action.params = { ...defaultParams(action.type), ...params };
      } else {
        action.params = params;
      }
    },
    validate(): boolean {
      if (!this.model.display_name.trim()) {
        notify.warning(this.$t('name_required'));
        return false;
      }
      if (!this.isRouting && !this.model.target_field) {
        notify.warning(this.$t('field_required'));
        return false;
      }
      if (!this.model.actions.length) {
        notify.warning(this.$t('add_at_least_one_step'));
        return false;
      }
      // The backend rejects a position-dependent step that reads its own target
      // (it would drift on every re-process). Block it here so the user gets the
      // inline explanation and the Read-from fix rather than a server error.
      if (this.nonIdempotentWarning) {
        notify.warning(
          this.$t('non_idempotent_steps_warning', {
            steps: this.nonIdempotentWarning,
            field: this.model.target_field,
          }),
        );
        return false;
      }
      // A routing rule with a fixed assignment needs a chosen sub-org, else it
      // would stamp an empty attribute.
      if (this.isRouting && !this.model.source) {
        const step = this.model.actions[0];
        const value = (step?.params || {}) as Record<string, unknown>;
        if (step?.type === 'set_value' && !value.value) {
          notify.warning(this.$t('choose_sub_organisation_to_assign'));
          return false;
        }
      }
      return true;
    },
    async save() {
      if (this.isReadOnly || !this.validate()) {
        return;
      }
      try {
        this.saving = true;
        const core = assembleApiCore(this.model);
        if (this.isEdit) {
          await transformationRulesApiService.update(this.rule_id, core);
        } else {
          const rule_key = this.model.rule_key || slugify(this.model.display_name);
          await transformationRulesApiService.create({
            ...core,
            doc_type: this.doc_type_key,
            scope: this.model.scope,
            rule_key,
            target_field: this.isRouting ? DOC_ATTRIBUTE_KEY : this.model.target_field,
          });
        }
        notify.success(this.$t('MSG_SAVE'));
        this.goBack();
      } catch (err) {
        notifyApiError(err);
        logError(err);
      } finally {
        this.saving = false;
      }
    },
    goBack() {
      this.$router.push(
        '/settings/transformation-rules/' + this.doc_type_key,
      );
    },
    // Fork this system default into an editable org copy and reopen the builder
    // on that copy, handing it over via router state to prefill without a refetch.
    async customizeRule() {
      if (!this.rule_id) {
        return;
      }
      try {
        this.customizing = true;
        const override = await transformationRulesApiService.customize(this.rule_id);
        this.$router.push({
          path: '/settings/transformation-rules/' + this.doc_type_key + '/' + override.id,
          state: { rule: JSON.parse(JSON.stringify(override)) },
        });
      } catch (err) {
        notifyApiError(err);
        logError(err);
      } finally {
        this.customizing = false;
      }
    },
  },
  // setup() hosts only the useRuleKey composable (composables must run here)
  // plus the state it reads reactively. rule_id / isReadOnly aren't props, so
  // they live here rather than data — but stay writable as this.rule_id /
  // this.isReadOnly from the Options methods. isEdit is an Options computed.
  setup() {
    const model = ref<TransformationBuilderModel>(emptyModel());
    const rule_id = ref('');
    // System-default rules (source_badge === 'system_default') are read-only.
    const isReadOnly = ref(false);
    const ruleKey = useRuleKey({
      getName: () => model.value.display_name,
      setKey: (value) => {
        model.value.rule_key = value;
      },
      isEdit: () => !!rule_id.value,
      isReadOnly: () => isReadOnly.value,
    });
    return {
      model,
      rule_id,
      isReadOnly,
      ...ruleKey,
      dropdowns: useDropdownStore(),
      saving: ref(false),
      customizing: ref(false),
    };
  },
});
</script>

